/** An arrow that points up, from the chosen icon pack. */
export const ArrowUpIcon = packIcon("arrow-up");
/** A bell, from the chosen icon pack. */
export const BellIcon = packIcon("bell");
/** A calendar, from the chosen icon pack. */
export const CalendarIcon = packIcon("calendar");
/** A check mark, from the chosen icon pack. */
export const CheckIcon = packIcon("check");
/** A chevron that points down, from the chosen icon pack. */
export const ChevronDownIcon = packIcon("chevron-down");
/** A chevron that points right, from the chosen icon pack. */
export const ChevronRightIcon = packIcon("chevron-right");
/** A check mark in a circle, from the chosen icon pack. */
export const CircleCheckIcon = packIcon("circle-check");
/** A cross in a circle, from the chosen icon pack. */
export const CircleXIcon = packIcon("circle-x");
/** A download arrow, from the chosen icon pack. */
export const DownloadIcon = packIcon("download");
/** A globe, from the chosen icon pack. */
export const GlobeIcon = packIcon("globe");
/** An expand mark, from the chosen icon pack. */
export const MaximizeIcon = packIcon("expand");
/** A speech bubble, from the chosen icon pack. */
export const MessageIcon = packIcon("message");
/** A play mark, from the chosen icon pack. */
export const PlayerPlayFilledIcon = packIcon("play");
/** A plus, from the chosen icon pack. */
export const PlusIcon = packIcon("plus");
/** A refresh mark, from the chosen icon pack. */
export const RefreshIcon = packIcon("refresh");
/** Sparkles, from the chosen icon pack. */
export const SparklesIcon = packIcon("sparkles");
/** Two people, from the chosen icon pack. */
export const UsersIcon = packIcon("users");
/** A close mark, from the chosen icon pack. */
export const XIcon = packIcon("x");

/** Two arrows that cross, for swapping two things. */
export const ArrowsShuffleIcon = ownIcon(
  <>
    <path d="M2 4.5h2.2c1.2 0 2.3.6 3 1.6l1.6 3.8c.7 1 1.8 1.6 3 1.6H14" />
    <path d="M2 11.5h2.2c1 0 1.9-.4 2.6-1.1M9.2 5.6c.7-.7 1.6-1.1 2.6-1.1H14" />
    <path d="M12 2.5l2 2-2 2M12 9.5l2 2-2 2" />
  </>,
);

/** Six dots, for a handle a person drags. */
export const GripVerticalIcon = ownIcon(
  <path d="M6 3.5h.01M10 3.5h.01M6 8h.01M10 8h.01M6 12.5h.01M10 12.5h.01" strokeWidth="2" />,
);

/** Two bars, for pause. */
export const PlayerPauseFilledIcon = ownIcon(<path d="M5.5 3.5v9M10.5 3.5v9" strokeWidth="2.5" />);

/** A bin, for remove. */
export const TrashIcon = ownIcon(
  <>
    <path d="M2.5 4.5h11M6 4.5V3a.5.5 0 0 1 .5-.5h3A.5.5 0 0 1 10 3v1.5" />
    <path d="M4 4.5l.6 8a1 1 0 0 0 1 .9h4.8a1 1 0 0 0 1-.9l.6-8M6.75 7v4M9.25 7v4" />
  </>,
);

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

"use client";

import { useId, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import { STATUS_TEXT } from "../../lib/status";
import { RollingText } from "../../parts/rolling-text";
import { ExpandRegion } from "../shared/expand-region";
import { CARD } from "./data";

/** Props for the card on file. */
export interface PaymentCardProps {
  onSaved: (message: string) => void;
}

const digitsOf = (value: string) => value.replace(/\D/g, "").slice(0, 16);
const groupDigits = (digits: string) => digits.replace(/(\d{4})(?=\d)/g, "$1 ");

/**
 * The card on file, drawn as a card. Update opens a short form; while a new
 * number is typed, the last four digits on the drawing turn over to match.
 * Escape or Cancel puts the old card back.
 */
export function PaymentCard({ onSaved }: PaymentCardProps) {
  const [card, setCard] = useState(CARD);
  const [editing, setEditing] = useState(false);
  const [number, setNumber] = useState("");
  const [expiry, setExpiry] = useState("");
  const [error, setError] = useState("");
  const id = useId();

  const digits = digitsOf(number);
  const shownLast4 = editing && digits.length >= 4 ? digits.slice(-4) : card.last4;
  const shownExpiry = editing && expiry.length === 5 ? expiry : card.expiry;

  const cancel = () => {
    setEditing(false);
    setNumber("");
    setExpiry("");
    setError("");
  };

  const save = () => {
    if (digits.length !== 16) return setError("Enter all 16 digits of the card number.");
    if (!/^(0[1-9]|1[0-2])\/\d{2}$/.test(expiry)) return setError("Enter the expiry as MM/YY.");
    setCard({ ...card, last4: digits.slice(-4), expiry });
    onSaved(`Card ending ${digits.slice(-4)} saved.`);
    cancel();
  };

  return (
    <div
      className="flex flex-col gap-4"
      onKeyDown={(event) => {
        if (event.key === "Escape" && editing) {
          event.preventDefault();
          cancel();
        }
      }}
    >
      <div className="flex flex-wrap items-end gap-4">
        <div
          role="img"
          aria-label={`${card.brand} card ending ${shownLast4}, expires ${shownExpiry}`}
          className="relative flex aspect-[1.6] w-56 flex-col justify-between overflow-hidden rounded-2xl bg-linear-to-br from-chart-1 to-chart-4 p-4 text-primary-foreground shadow-md"
        >
          <span aria-hidden="true" className="absolute -top-8 -right-6 size-28 rounded-full bg-chart-2 opacity-60 blur-xl" />
          <span className="relative flex items-center justify-between text-sm font-semibold">
            Fernhill billing
            <span className="text-xs font-medium">{card.brand}</span>
          </span>
          <span className="relative font-mono text-base tracking-widest">
            •••• <RollingText text={shownLast4} />
          </span>
          <span className="relative flex items-center justify-between text-xs">
            <span className="truncate">{card.holder}</span>
            <RollingText text={shownExpiry} />
          </span>
        </div>
        {editing ? null : (
          <Button variant="outline" onClick={() => setEditing(true)} aria-expanded={editing} aria-controls={id}>
            Update card
          </Button>
        )}
      </div>
      <ExpandRegion open={editing} id={id}>
        <form
          className="grid gap-3 @md:grid-cols-[1fr_7rem]"
          onSubmit={(event) => {
            event.preventDefault();
            save();
          }}
        >
          <div className="flex flex-col gap-1.5">
            <label htmlFor={`${id}-number`} className="text-sm font-medium">
              Card number
            </label>
            <Input
              id={`${id}-number`}
              inputMode="numeric"
              autoComplete="cc-number"
              placeholder="4000 0000 0000 0000"
              value={groupDigits(digits)}
              onChange={(event) => setNumber(event.target.value)}
            />
          </div>
          <div className="flex flex-col gap-1.5">
            <label htmlFor={`${id}-expiry`} className="text-sm font-medium">
              Expiry
            </label>
            <Input
              id={`${id}-expiry`}
              inputMode="numeric"
              autoComplete="cc-exp"
              placeholder="MM/YY"
              value={expiry}
              onChange={(event) => {
                const raw = event.target.value.replace(/\D/g, "").slice(0, 4);
                setExpiry(raw.length > 2 ? `${raw.slice(0, 2)}/${raw.slice(2)}` : raw);
              }}
            />
          </div>
          <p role="alert" className={cn("min-h-4 text-xs @md:col-span-2", STATUS_TEXT.bad)}>
            {error}
          </p>
          <div className="flex justify-end gap-2 @md:col-span-2">
            <Button type="button" variant="ghost" onClick={cancel}>
              Cancel
            </Button>
            <Button type="submit">Save card</Button>
          </div>
        </form>
      </ExpandRegion>
    </div>
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

