import { Button } from "@/components/ui/button";

import { formatWhole } from "../../lib/format";
import { focusRoving, rovingIndex } from "../shared/roving";
import { type Period, type Plan, type PlanId, priceFor } from "./data";

/** Props for the plan picker. */
export interface PlanPickerProps {
  plans: Plan[];
  current: PlanId;
  currentPeriod: Period;
  selected: PlanId;
  onSelect: (id: PlanId) => void;
  period: Period;
  onPeriod: (period: Period) => void;
  onConfirm: () => void;
  onCancel: () => void;
}

const WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };
const PERIODS: { value: Period; label: string }[] = [
  { value: "month", label: "Monthly" },
  { value: "year", label: "Yearly, 2 months free" },
];

/**
 * The plans as one radio group with a highlight that glides to the choice.
 * Arrows, Home and End move and choose. The total under it rolls to the new
 * price. Escape, handled by the card around it, closes the picker.
 */
export function PlanPicker({ plans, current, currentPeriod, selected, onSelect, period, onPeriod, onConfirm, onCancel }: PlanPickerProps) {
  const groupRef = useRef<HTMLDivElement>(null);
  const reduceMotion = useReducedMotion();
  const glideId = useId();
  const index = plans.findIndex((plan) => plan.id === selected);
  const chosen = plans[index] ?? plans[0]!;
  const same = chosen.id === current && period === currentPeriod;

  return (
    <div className="flex flex-col gap-4">
      <SegmentedControl aria-label="Billing period" options={PERIODS} value={period} onValueChange={onPeriod} />
      <div
        ref={groupRef}
        role="radiogroup"
        aria-label="Plans"
        className="grid gap-2 @xl:grid-cols-3"
        onKeyDown={(event) => {
          const next = rovingIndex(event, index, plans.length);
          const plan = next === null ? undefined : plans[next];
          if (next === null || !plan) return;
          event.preventDefault();
          onSelect(plan.id);
          focusRoving(groupRef.current, next);
        }}
      >
        {plans.map((plan, position) => {
          const checked = plan.id === selected;
          return (
            <div
              key={plan.id}
              role="radio"
              aria-checked={checked}
              tabIndex={checked ? 0 : -1}
              data-roving={position}
              onClick={() => onSelect(plan.id)}
              onKeyDown={(event) => (event.key === " " || event.key === "Enter" ? (event.preventDefault(), onSelect(plan.id)) : undefined)}
              className="relative isolate flex cursor-pointer flex-col gap-1 rounded-xl border border-border p-3 outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              {checked ? (
                <motion.span
                  layoutId={glideId}
                  aria-hidden="true"
                  className="absolute -inset-px -z-10 rounded-xl border-2 border-chart-1 bg-chart-1/10"
                  transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 42 }}
                />
              ) : null}
              <span className="flex items-center justify-between gap-2 text-sm font-semibold">
                {plan.name}
                {plan.id === current ? <span className="text-xs font-normal text-muted-foreground">Current</span> : null}
              </span>
              <span className="text-lg font-semibold tabular-nums">
                ${formatWhole(priceFor(plan, period))}
                <span className="text-xs font-normal text-muted-foreground"> a {period}</span>
              </span>
              <span className="text-xs text-muted-foreground">{plan.blurb}</span>
              <span className="text-xs text-muted-foreground">
                {plan.practitioners} practitioners, {formatWhole(plan.texts)} texts, {plan.storage} GB
              </span>
            </div>
          );
        })}
      </div>
      <div className="flex flex-wrap items-center justify-between gap-3 border-t border-border pt-4">
        <p className="text-sm" aria-live="polite">
          {same ? (
            "Pick a plan or a billing period to switch to."
          ) : (
            <>
              {chosen.name} from Dec 1: <span className="font-semibold">$</span>
              <NumberTicker value={priceFor(chosen, period)} format={WHOLE} className="font-semibold" />
              <span className="text-muted-foreground"> a {period}</span>
            </>
          )}
        </p>
        <div className="flex gap-2">
          <Button variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
          <Button onClick={onConfirm} disabled={same}>
            Switch plan
          </Button>
        </div>
      </div>
    </div>
  );
}

import type { KeyboardEvent } from "react";

/** Which arrow keys step through a list. */
export type RovingAxis = "vertical" | "horizontal" | "both";

const BACK = { vertical: ["ArrowUp"], horizontal: ["ArrowLeft"], both: ["ArrowUp", "ArrowLeft"] } as const;
const FORWARD = { vertical: ["ArrowDown"], horizontal: ["ArrowRight"], both: ["ArrowDown", "ArrowRight"] } as const;

/**
 * Reads one key press on a list of `count` items and returns the index it
 * moves to, or null for a key the list does not handle. Arrows step and wrap
 * at the ends; Home and End go to the first and last item. The caller
 * prevents the default only when an index comes back.
 */
export function rovingIndex(event: KeyboardEvent, current: number, count: number, axis: RovingAxis = "both"): number | null {
  if (count === 0) return null;
  const back: readonly string[] = BACK[axis];
  const forward: readonly string[] = FORWARD[axis];
  if (back.includes(event.key)) return (current - 1 + count) % count;
  if (forward.includes(event.key)) return (current + 1) % count;
  if (event.key === "Home") return 0;
  if (event.key === "End") return count - 1;
  return null;
}

/** Moves focus to the element in `container` that carries `data-roving` equal to `index`, after React has painted. */
export function focusRoving(container: HTMLElement | null, index: number) {
  requestAnimationFrame(() => {
    container?.querySelector<HTMLElement>(`[data-roving="${index}"]`)?.focus();
  });
}

