import { motion, useReducedMotion } from "motion/react";
import { type ReactNode, useEffect, useRef, useState } from "react";

/** Props for a box whose height follows its content on a spring. */
export interface SpringHeightProps {
  children: ReactNode;
  className?: string;
}

/**
 * Measures its content and springs its own height to match, with no bounce,
 * so whatever sits under it glides instead of jumping. Under reduced motion
 * the height changes at once.
 */
export function SpringHeight({ children, className }: SpringHeightProps) {
  const innerRef = useRef<HTMLDivElement>(null);
  const [height, setHeight] = useState<number | "auto">("auto");
  const reduceMotion = useReducedMotion();

  useEffect(() => {
    const inner = innerRef.current;
    if (!inner) return;
    const observer = new ResizeObserver(([entry]) => {
      if (entry) setHeight(entry.borderBoxSize[0]?.blockSize ?? entry.contentRect.height);
    });
    observer.observe(inner);
    return () => observer.disconnect();
  }, []);

  return (
    <motion.div
      initial={false}
      animate={{ height }}
      transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 360, damping: 38 }}
      className="overflow-hidden"
    >
      <div ref={innerRef} className={className}>
        {children}
      </div>
    </motion.div>
  );
}

"use client";

import type { CSSProperties } from "react";
import { AlertTriangleIcon } from "@/components/blocks/parts/icons";
import { cn } from "@/lib/utils";

import { STATUS_SURFACE, STATUS_TEXT } from "../../lib/status";
import { RollingText } from "../../parts/rolling-text";

/** Props for one usage bar against its limit. */
export interface UsageMeterProps {
  label: string;
  used: number;
  limit: number;
  /** Writes a figure with its unit, such as "1,240 texts". */
  format: (value: number) => string;
  /** The fill colour, such as `bg-chart-2`. */
  tone: string;
  /** Where the bar sits in a staggered fill, from 0. */
  order?: number;
  /** A short note under the bar, such as the overage price. */
  note?: string;
  /** Fades the meter when another meter is hovered. */
  dimmed?: boolean;
  onHover?: (hovered: boolean) => void;
}

const DELAYS = ["delay-0", "delay-100", "delay-200", "delay-300"];

/** The share of the limit at which a meter warns. */
export const NEAR_LIMIT = 0.8;

/**
 * One resource against its limit: the figures, a bar that fills with a short
 * stagger, and a flag once usage passes 80 percent. The flag uses a word and
 * an icon as well as colour, so it never relies on colour alone.
 */
export function UsageMeter({ label, used, limit, format, tone, order = 0, note, dimmed, onHover }: UsageMeterProps) {
  const share = limit > 0 ? used / limit : 0;
  const over = share > 1;
  const near = !over && share >= NEAR_LIMIT;
  const state = over ? "bad" : near ? "watch" : null;
  return (
    <div
      className={cn("flex flex-col gap-2 transition-opacity duration-200", dimmed ? "opacity-45" : "opacity-100")}
      onPointerEnter={() => onHover?.(true)}
      onPointerLeave={() => onHover?.(false)}
    >
      <div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
        <span className="text-sm font-medium">{label}</span>
        <span className="text-sm text-muted-foreground tabular-nums">
          <RollingText text={format(used)} className="text-foreground" /> of <RollingText text={format(limit)} />
        </span>
      </div>
      <div
        role="meter"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={limit}
        aria-valuenow={Math.min(used, limit)}
        aria-valuetext={`${format(used)} of ${format(limit)}`}
        className="relative h-2 overflow-hidden rounded-full bg-muted"
      >
        <span
          className={cn(
            "absolute inset-y-0 left-0 w-(--fill) rounded-full motion-safe:transition-all motion-safe:duration-700 motion-safe:ease-out",
            DELAYS[order % DELAYS.length],
            over ? "bg-chart-5" : tone,
          )}
          // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
          style={{ "--fill": `${Math.min(100, share * 100)}%` } as CSSProperties}
        />
      </div>
      <div className="flex min-h-5 flex-wrap items-center gap-2 text-xs text-muted-foreground">
        {state ? (
          <span className={cn("inline-flex items-center gap-1 rounded-full px-2 py-0.5 font-medium", STATUS_SURFACE[state], STATUS_TEXT[state])}>
            <AlertTriangleIcon aria-hidden="true" className="size-3" />
            {over ? "Over the limit" : "Near the limit"}
          </span>
        ) : null}
        {note ? <span>{note}</span> : null}
      </div>
    </div>
  );
}
